```js
#!/usr/bin/env node
'use strict';

const fs = require('fs');
const path = require('path');

const README_PATH = path.join(__dirname, 'README.md');
const INDEX_PATH = path.join(__dirname, 'INDEX.md');
const FENCE_RE = /^\s{0,3}(```+|~~~+)/;
const HEADING_RE = /^\s{0,3}#{1,6}(\s|$)/;

function extractHeadings(markdown) {
  const headings = [];
  let fence = null;

  for (const line of markdown.split(/\r?\n/)) {
    const fenceMatch = line.match(FENCE_RE);
    if (fenceMatch) {
      const marker = fenceMatch[1][0];
      if (fence === null) fence = marker;
      else if (fence === marker) fence = null;
      continue;
    }
    if (fence !== null) continue;
    if (!HEADING_RE.test(line)) continue;
    const heading = line.trim();
    if (heading.length > 0) headings.push(heading);
  }

  return headings;
}

function main() {
  const markdown = fs.readFileSync(README_PATH, 'utf8');
  const headings = extractHeadings(markdown);
  fs.writeFileSync(INDEX_PATH, headings.length ? headings.join('\n') + '\n' : '', 'utf8');
  console.log(`Wrote ${headings.length} heading(s) to ${path.basename(INDEX_PATH)}`);
  for (const h of headings) console.log(`  ${h}`);
}

main();
```

Note: `line.trim()` removes leading indentation and trailing whitespace — for headings that keeps "# Title". Good.

